#include <Arduino.h>
#include <TFT_eSPI.h>

// Wyświetlacz ST7789
TFT_eSPI tft = TFT_eSPI();

void setup() {

    Serial.begin(115200);
    delay(500);

    Serial.println();
    Serial.println("LILYGO T-EMBED CC1101");
    Serial.println("DISPLAY TEST VERSION 2");

    // Włączenie zasilania urządzeń na płytce
    pinMode(15, OUTPUT);
    digitalWrite(15, HIGH);

    delay(200);

    // Włączenie podświetlenia
    pinMode(21, OUTPUT);
    digitalWrite(21, HIGH);

    delay(300);

    Serial.println("Initializing display...");

    // Inicjalizacja wyświetlacza
    tft.init();

    // Poziome ustawienie ekranu
    tft.setRotation(3);

    Serial.print("Width: ");
    Serial.println(tft.width());

    Serial.print("Height: ");
    Serial.println(tft.height());

    // Test czerwony
    tft.fillScreen(TFT_RED);
    delay(1000);

    // Test zielony
    tft.fillScreen(TFT_GREEN);
    delay(1000);

    // Test niebieski
    tft.fillScreen(TFT_BLUE);
    delay(1000);

    // Ekran końcowy
    tft.fillScreen(TFT_BLACK);

    tft.drawRect(
        0, 0,
        tft.width(),
        tft.height(),
        TFT_CYAN
    );

    tft.setTextColor(TFT_WHITE, TFT_BLACK);
    tft.setTextSize(2);

    tft.setCursor(75, 45);
    tft.println("LILYGO");

    tft.setCursor(55, 85);
    tft.println("DISPLAY OK");

    tft.setTextSize(1);
    tft.setCursor(95, 125);
    tft.println("ST7789");

    Serial.println("DISPLAY TEST FINISHED");
}

void loop() {
    delay(1000);
}
